package io.phext.libphext;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;

/**
 * The shared libphext 0.6.1 range conformance fixtures
 * ({@code tests/fixtures/ranges/}, generated by calling the libphext-rs
 * 0.6.1 API itself — see FIXTURES-RANGES.md in the fixture set's home).
 * One harness test per case; a case passes only if every recorded op
 * passes, consuming {@code expected.tsv} exactly as FIXTURES-RANGES.md
 * specifies:
 * <ul>
 *   <li>{@code parse_point} / {@code parse_range}: canonical form or a
 *       parse error;</li>
 *   <li>{@code resolve_point}: the {@code universe|coordinate|offset}
 *       resolution (offset in Unicode scalar values) or a resolution
 *       error;</li>
 *   <li>{@code fetch_point} / {@code fetch_range}: byte-exact result
 *       bytes from {@code results/NN.txt}, plus the {@code resolved} flag
 *       reproduced via {@code resolvePoint} / {@code resolveRange} — the
 *       resolved-but-empty and unresolved situations stay
 *       distinguishable.</li>
 * </ul>
 * Ops apply to chain 0 of {@code Phext.parseChains(input)}.
 */
public final class RangeFixtureTests {
    private RangeFixtureTests() {
    }

    private static String sha256Hex(byte[] bytes) throws Exception {
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(bytes);
        StringBuilder out = new StringBuilder();
        for (byte b : digest) {
            out.append(String.format("%02x", b));
        }
        return out.toString();
    }

    private static String field(String[] fields, String key) {
        for (String f : fields) {
            int eq = f.indexOf('=');
            if (eq > 0 && f.substring(0, eq).equals(key)) {
                return f.substring(eq + 1);
            }
        }
        throw new AssertionError("missing field " + key);
    }

    public static void register() {
        Path fixturesDir = TestMain.repoRoot.resolve("tests/fixtures/ranges");
        List<String> caseNames;
        try {
            String tsv = Files.readString(fixturesDir.resolve("cases.tsv"), StandardCharsets.UTF_8);
            caseNames = new ArrayList<>();
            for (String line : tsv.split("\n")) {
                if (line.isBlank() || line.startsWith("case\t")) {
                    continue;
                }
                caseNames.add(line.split("\t")[0]);
            }
        } catch (Exception e) {
            TestMain.test("RangeFixtureTests", "cases.tsv readable", () -> {
                throw e;
            });
            return;
        }
        A.eq(6, caseNames.size(), "range fixture case count");
        for (String caseName : caseNames) {
            TestMain.test("RangeFixtureTests", caseName, () -> runCase(fixturesDir.resolve(caseName)));
        }
    }

    private static void runCase(Path caseDir) throws Exception {
        String tsv = Files.readString(caseDir.resolve("expected.tsv"), StandardCharsets.UTF_8);
        String[] lines = tsv.split("\n");
        String caseName = null;
        long expectedInputBytes = -1;
        String expectedInputSha = null;
        long expectedOps = -1;
        for (String line : lines) {
            String[] head = line.split("\t", -1);
            if (head.length >= 2 && head[0].equals("case")) {
                caseName = head[1];
            } else if (head.length >= 2 && head[0].equals("input_bytes")) {
                expectedInputBytes = Long.parseLong(head[1]);
            } else if (head.length >= 2 && head[0].equals("input_sha256")) {
                expectedInputSha = head[1];
            } else if (head.length >= 2 && head[0].equals("ops")) {
                expectedOps = Long.parseLong(head[1]);
            }
        }

        byte[] inputBytes = Files.readAllBytes(caseDir.resolve("input.phext"));
        A.eq(expectedInputBytes, inputBytes.length, caseName + " input_bytes");
        A.eq(expectedInputSha, sha256Hex(inputBytes), caseName + " input_sha256");
        String input = new String(inputBytes, StandardCharsets.UTF_8);
        Chain chain = Phext.parseChains(input).get(0);

        long ops = 0;
        for (String line : lines) {
            String[] fields = line.split("\t", -1);
            if (fields.length < 3 || !fields[0].equals("op")) {
                continue;
            }
            ops += 1;
            String kind = fields[1];
            String addr = fields[2];
            String at = caseName + " op " + ops + " (" + kind + " " + addr + ")";
            switch (kind) {
                case "parse_point" -> {
                    boolean error = field(fields, "error").equals("true");
                    PointAddress parsed = Phext.parsePointAddress(addr);
                    if (parsed == null) {
                        A.isTrue(error, at + ": expected parse error, got success");
                    } else {
                        A.isFalse(error, at + ": expected success, got parse error");
                        A.eq(field(fields, "canonical"), parsed.toString(), at + ": canonical mismatch");
                    }
                }
                case "parse_range" -> {
                    boolean error = field(fields, "error").equals("true");
                    RangeAddress parsed = Phext.parseRangeAddress(addr);
                    if (parsed == null) {
                        A.isTrue(error, at + ": expected parse error, got success");
                    } else {
                        A.isFalse(error, at + ": expected success, got parse error");
                        A.eq(field(fields, "canonical"), parsed.toString(), at + ": canonical mismatch");
                    }
                }
                case "resolve_point" -> {
                    boolean error = field(fields, "error").equals("true");
                    PointAddress point = Phext.parsePointAddress(addr);
                    A.notNull(point, at + ": resolve op input parses");
                    Chain.ResolvedPoint resolved = chain.resolvePoint(point);
                    if (resolved == null) {
                        A.isTrue(error, at + ": expected resolution error, got success");
                    } else {
                        A.isFalse(error, at + ": expected success, got resolution error");
                        String want = resolved.universe() + "|" + resolved.coordinate() + "|" + resolved.offset();
                        A.eq(field(fields, "resolve"), want, at + ": resolution mismatch");
                    }
                }
                case "fetch_point" -> {
                    boolean resolvedFlag = field(fields, "resolved").equals("true");
                    PointAddress point = Phext.parsePointAddress(addr);
                    boolean actualResolved = point != null && chain.resolvePoint(point) != null;
                    A.eq(resolvedFlag, actualResolved, at + ": resolved flag mismatch");
                    byte[] expected = Files.readAllBytes(caseDir.resolve(field(fields, "file")));
                    byte[] actual = chain.fetchPoint(addr).getBytes(StandardCharsets.UTF_8);
                    A.eqBytes(expected, actual, at + ": fetch_point bytes mismatch");
                }
                case "fetch_range" -> {
                    boolean resolvedFlag = field(fields, "resolved").equals("true");
                    RangeAddress range = Phext.parseRangeAddress(addr);
                    boolean actualResolved = range != null && chain.resolveRange(range) != null;
                    A.eq(resolvedFlag, actualResolved, at + ": resolved flag mismatch");
                    byte[] expected = Files.readAllBytes(caseDir.resolve(field(fields, "file")));
                    byte[] actual = chain.fetchRange(addr).getBytes(StandardCharsets.UTF_8);
                    A.eqBytes(expected, actual, at + ": fetch_range bytes mismatch");
                }
                default -> throw new AssertionError(at + ": unknown op kind " + kind);
            }
        }
        A.eq(expectedOps, ops, caseName + " op count");
    }
}
